import Foundation
struct Invoice {
    let amounts: [Decimal]
    let deliveryFee: Decimal
    func totalForCheckout() -> Decimal {
        let subtotal = amounts.reduce(0, +)
        let delivery = subtotal >= 100 ? Decimal(0) : deliveryFee
        let tax = subtotal * Decimal(string: "0.19")!
        return subtotal + delivery + tax
    }
    func totalForReceipt() -> Decimal {
        let subtotal = amounts.reduce(0, +)
        let delivery = subtotal >= 100 ? Decimal(0) : deliveryFee
        let tax = subtotal * Decimal(string: "0.19")!
        return subtotal + delivery + tax
    }
}

