import Foundation
import OSLog
import SwiftUI

struct Recipe: Identifiable, Decodable, Sendable {
    let id: Int
    let name: String
}

struct RecipeClient: Sendable {
    func recipes(matching text: String) async throws -> [Recipe] {
        var components = URLComponents(string: "https://example.org/recipes")
        components?.queryItems = [URLQueryItem(name: "q", value: text)]
        guard let url = components?.url else { throw URLError(.badURL) }
        let (data, _) = try await URLSession.shared.data(from: url)
        return try JSONDecoder().decode([Recipe].self, from: data)
    }
}

@MainActor @Observable
final class RecipeSearchModel {
    enum State { case idle, loading, results([Recipe]), failed }

    var text = ""
    private(set) var state = State.idle
    private let client = RecipeClient()
    private let logger = Logger(subsystem: "example", category: "search")

    func search() async {
        guard !text.isEmpty else { state = .idle; return }
        state = .loading
        do {
            try await Task.sleep(for: .milliseconds(300))
            state = .results(try await client.recipes(matching: text))
        } catch is CancellationError {
            return
        } catch let error as URLError where error.code == .cancelled {
            return
        } catch {
            logger.error("Recipe search failed: \(error)")
            state = .failed
        }
    }
}

struct RecipeSearchView: View {
    @State private var model = RecipeSearchModel()

    var body: some View {
        Group {
            switch model.state {
            case .idle: Text("Search for a recipe")
            case .loading: ProgressView()
            case let .results(recipes): List(recipes) { Text($0.name) }
            case .failed: Text("Search failed. Try again.")
            }
        }
        .searchable(text: $model.text)
        .task(id: model.text) { await model.search() }
    }
}

