import Foundation
import OSLog
import SwiftUI

struct Recipe: Identifiable, Decodable, Sendable {
    let id: Int
    let name: String
}

struct RecipeClient {
    func load(from url: URL) async throws -> Data {
        let (data, response) = try await URLSession.shared.data(from: url)
        guard let response = response as? HTTPURLResponse, response.statusCode == 200 else {
            throw URLError(.cancelled)
        }
        return data
    }
}

@MainActor @Observable
final class RecipeFeedModel {
    enum State { case idle, loading, loaded([Recipe]), failed }

    private(set) var state = State.idle
    private let client = RecipeClient()
    private let logger = Logger(subsystem: "example", category: "feed")

    func refresh() async {
        guard let url = URL(string: "https://example.org/recipes/today") else { return }
        state = .loading
        do {
            let data = try await client.load(from: url)
            state = .loaded(try JSONDecoder().decode([Recipe].self, from: data))
        } catch let error as URLError where error.code == .cancelled {
            return
        } catch {
            logger.error("Recipe refresh failed: \(error)")
            state = .failed
        }
    }
}

struct RecipeFeedView: View {
    @State private var model = RecipeFeedModel()

    var body: some View {
        VStack {
            switch model.state {
            case .idle: Text("Today's recipes")
            case .loading: ProgressView()
            case let .loaded(recipes): List(recipes) { Text($0.name) }
            case .failed: Text("Couldn't load recipes.")
            }
            Button("Refresh") { Task { await model.refresh() } }
        }
    }
}

