import SwiftUI

struct Chore: Identifiable {
    let id: Int
    let title: String
    let due: Date
    let isDone: Bool
}

struct ChoreRow: View {
    let chore: Chore
    let now: Date

    var body: some View {
        HStack {
            Text(chore.title)
            Spacer()
            if !chore.isDone && chore.due < now {
                Text("Overdue").foregroundStyle(.red)
            } else if !chore.isDone && chore.due < now.addingTimeInterval(86_400) {
                Text("Due soon").foregroundStyle(.orange)
            }
        }
    }
}

struct ChoreSummary: View {
    let chores: [Chore]
    let now: Date

    var body: some View {
        let overdue = chores.filter { !$0.isDone && $0.due < now }.count
        let dueSoon = chores.filter { !$0.isDone && $0.due >= now && $0.due < now.addingTimeInterval(86_400) }.count
        Text("\(overdue) overdue, \(dueSoon) due soon")
    }
}

