import SwiftUI

struct Station: Identifiable, Decodable, Sendable {
    let id: String
    let name: String
    let minutesAway: Int
}

protocol StationSearching: Sendable {
    func stations(near query: String) async throws -> [Station]
}

struct LiveStationSearch: StationSearching {
    func stations(near query: String) async throws -> [Station] {
        var components = URLComponents(string: "https://example.org/stations")
        components?.queryItems = [URLQueryItem(name: "q", value: query)]
        guard let url = components?.url else { throw URLError(.badURL) }
        let (data, _) = try await URLSession.shared.data(from: url)
        return try JSONDecoder().decode([Station].self, from: data)
    }
}

@MainActor @Observable
final class StationSearchModel {
    enum State { case idle, loading, results([Station]), failed }

    var query: String
    private(set) var state = State.idle
    private let client: any StationSearching

    init(query: String = "", client: any StationSearching = LiveStationSearch()) {
        self.query = query
        self.client = client
    }

    func search() async {
        guard !query.isEmpty else { state = .idle; return }
        state = .loading
        do { state = .results(try await client.stations(near: query)) }
        catch { state = .failed }
    }
}

struct StationSearchView: View {
    @State private var model: StationSearchModel

    init(model: StationSearchModel = StationSearchModel()) {
        _model = State(initialValue: model)
    }

    var body: some View {
        StationSearchContent(state: model.state)
            .navigationTitle("Stations")
            .searchable(text: $model.query)
            .task(id: model.query) { await model.search() }
    }
}

private struct StationSearchContent: View {
    let state: StationSearchModel.State

    var body: some View {
        switch state {
        case .idle:
            ContentUnavailableView("Find a Station", systemImage: "tram", description: Text("Search by stop name."))
        case .loading:
            ProgressView("Searching…")
        case let .results(stations):
            List(stations) { station in
                LabeledContent(station.name, value: "\(station.minutesAway) min")
            }
        case .failed:
            ContentUnavailableView("Stations Unavailable", systemImage: "wifi.exclamationmark", description: Text("Try again in a moment."))
        }
    }
}

private struct SampleStationSearch: StationSearching {
    var results: [Station] = []
    var fails = false

    func stations(near query: String) async throws -> [Station] {
        if fails { throw URLError(.notConnectedToInternet) }
        return results
    }
}

